from ortools.sat.python import cp_model
import itertools
import json

def main():
    model = cp_model.CpModel()

    experiments = ['Alpha', 'Beta', 'Gamma', 'Delta', 'Epsilon', 'Zeta', 'Eta']
    QPUs = [1, 2, 3, 4, 5, 6, 7]
    positions = [1, 2, 3, 4, 5, 6, 7]

    duration = {
        'Alpha': {3: 89, 2: 39, 4: 54, 7: 34, 1: 71, 6: 92, 5: 56},
        'Beta': {2: 19, 3: 13, 6: 81, 5: 46, 1: 91, 4: 73, 7: 27},
        'Gamma': {1: 66, 2: 95, 6: 48, 7: 24, 3: 96, 4: 18, 5: 14},
        'Delta': {2: 48, 6: 46, 1: 78, 7: 94, 3: 19, 4: 68, 5: 63},
        'Epsilon': {6: 60, 4: 28, 3: 91, 5: 75, 1: 52, 2: 9, 7: 7},
        'Zeta': {7: 33, 5: 98, 2: 37, 1: 11, 4: 2, 3: 30, 6: 38},
        'Eta': {2: 83, 4: 45, 5: 37, 7: 77, 6: 52, 3: 88, 1: 52}
    }

    x = {}
    for e in experiments:
        for p in positions:
            for q in QPUs:
                x[(e, p, q)] = model.NewBoolVar(f'x_{e}_{p}_{q}')

    start = {}
    max_possible_time = sum(duration[e][q] for e in experiments for q in QPUs)
    for e in experiments:
        for q in QPUs:
            start[(e, q)] = model.NewIntVar(0, max_possible_time, f'start_{e}_{q}')

    makespan = model.NewIntVar(0, max_possible_time, 'makespan')

    for e in experiments:
        for p in positions:
            model.AddExactlyOne(x[(e, p, q)] for q in QPUs)

    for e in experiments:
        for q in QPUs:
            model.AddExactlyOne(x[(e, p, q)] for p in positions)

    M = max_possible_time

    for e in experiments:
        for p in range(1, 7):
            for q1 in QPUs:
                for q2 in QPUs:
                    if q1 == q2:
                        continue
                    model.Add(start[(e, q2)] >= start[(e, q1)] + duration[e][q1] - 
                             M * (2 - x[(e, p, q1)] - x[(e, p+1, q2)]))

    for q in QPUs:
        for i in range(len(experiments)):
            for j in range(i + 1, len(experiments)):
                e1 = experiments[i]
                e2 = experiments[j]

                e1_before_e2 = model.NewBoolVar(f'order_{q}_{e1}_{e2}')

                model.Add(start[(e2, q)] >= start[(e1, q)] + duration[e1][q]).OnlyEnforceIf(e1_before_e2)

                model.Add(start[(e1, q)] >= start[(e2, q)] + duration[e2][q]).OnlyEnforceIf(e1_before_e2.Not())

    for e in experiments:
        for q in QPUs:
            model.Add(makespan >= start[(e, q)] + duration[e][q])

    model.Minimize(makespan)

    solver = cp_model.CpSolver()
    solver.parameters.max_time_in_seconds = 300.0
    solver.parameters.num_search_workers = 8

    status = solver.Solve(model)

    if status in (cp_model.OPTIMAL, cp_model.FEASIBLE):
        start_times = []
        for e in experiments:
            exp_start_times = []
            for q in QPUs:
                exp_start_times.append(solver.Value(start[(e, q)]))
            start_times.append(exp_start_times)
        result = {
            "start_times": start_times,
            "makespan": solver.Value(makespan)
        }
        print(json.dumps(result))
    else:
        print(json.dumps({"start_times": [], "makespan": -1}))

if __name__ == "__main__":
    main()
